// Example: resumable client usage
ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
defer cancel()

s, err := client.StartResumableStream(ctx, &StartStreamOpts{Model: "redwood-1.1"})
if err != nil {
  return fmt.Errorf("start stream: %w", err)
}

// Backpressure: we only send when credits are available
for _, chunk := range producer.Chunks() {
  select {
  case <-ctx.Done():
    s.CloseWithReason(ctx, "client_cancelled")
    return ctx.Err()
  default:
  }
  if !s.WaitForCredits(ctx, 1) {
    // WaitForCredits returns false when context cancelled or stream closed
    return errors.New("stream closed while waiting for credits")
  }
  if err := s.Send(ctx, chunk); err != nil {
    // Send will attempt reconnect/resume if eligible; it returns an error if user cancelled
    return err
  }
}

// Close and flush gracefully
if err := s.CloseWithReason(ctx, "normal_shutdown"); err != nil {
  return err
}
